package io.github.long0823.tclviewer;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;
public class SettingsTest extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private View find(View view,String value){if(value.equals("TVのIPアドレス")&&!(view instanceof EditText)){}else if(value.equals(view.getContentDescription())||(view instanceof TextView&&value.contentEquals(((TextView)view).getText())))return view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){View found=find(g.getChildAt(i),value);if(found!=null)return found;}}return null;}
 public void onStart(){Bundle out=new Bundle();MainActivity a=null;try{getTargetContext().getSharedPreferences("MainActivity",0).edit().clear().commit();getTargetContext().getFileStreamPath("profile.ini").delete();a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1000);final MainActivity activity=a;java.lang.reflect.Field f=MainActivity.class.getDeclaredField("settingsDialog");f.setAccessible(true);AlertDialog dialog=(AlertDialog)f.get(a);if(dialog==null)throw new Exception("Initial setup did not open");final boolean[] input={false},saved={false};runOnMainSync(()->{EditText host=(EditText)find(dialog.getWindow().getDecorView(),"TVのIPアドレス");if(host==null)throw new AssertionError("IP field absent");host.setText("192.168.0.160");input[0]=host.isEnabled()&&host.getText().toString().equals("192.168.0.160");View save=find(dialog.getWindow().getDecorView(),"IP・チューナーを保存");save.performClick();saved[0]=activity.getPreferences(0).getString("pending_host","").equals("192.168.0.160");});if(!input[0]||!saved[0])throw new Exception("Initial IP save failed");out.putBoolean("initial_ip_editable",input[0]);out.putBoolean("ip_saved_without_ini",saved[0]);out.putString("result","PASS");runOnMainSync(activity::finish);finish(-1,out);}catch(Throwable e){out.putString("result","FAIL "+e.toString());finish(0,out);}}
}